#include <bits/stdc++.h>

using i64 = long long;
using namespace std;

constexpr int N = 8005, M = 805;

int n, m;
int d[N], l[N], s[N], add[N][M];
int head[N], nxt[N], to[N], tot;
int it[N][M], pool[N * M], pp;

void pre(int x) {
	s[x] = 1;
	l[x] = 0;
	for (int i = head[x]; i; i = nxt[i]) {
		int y = to[i];
		pre(y);
		if (d[y] >= d[l[x]]) {
			l[x] = y;
		}
		s[x] += s[y];
	}
	d[x] = d[l[x]] + 1;
}

inline int& DP(int x, int i, int j) {
	return pool[it[x][i] + j];
}
inline int getDP(int x, int i, int j) {
	if (j >= d[x]) {
		return i * s[x];
	}
	if (i > m) {
		return 0;
	}
	return pool[it[x][i] + j] + add[x][i];
}

void dfs(int x) {
	for (int i = 1; i <= m; ++i) {
		add[x][i] = 0;
	}

	if (!l[x]) {
		for (int i = 1; i <= m; ++i) {
			DP(x, i, 0) = i;
		}
		return;
	}

	for (int i = 1; i <= m; ++i) {
		it[l[x]][i] = it[x][i] + 1;
	}
	dfs(l[x]);

	for (int i = 1; i <= m; ++i) {
		add[x][i] = add[l[x]][i];
		DP(x, i, 0) = getDP(l[x], i + 1, 0) - add[x][i];
	}

	int ls = pp;

	for (int i = head[x]; i; i = nxt[i]) {
		int y = to[i];
		if (y != l[x]) {
			for (int j = 1; j <= m; ++j) {
				it[y][j] = pp;
				pp += d[y];
			}
			memset(pool + it[y][1], 0, m * d[y] * 4);
			dfs(y);
		}
	}

	for (int i = 1; i <= m; ++i) {
		int S = 0;
		for (int j = head[x]; j; j = nxt[j]) {
			S += getDP(to[j], i, i - 1);
		}
		add[x][i] += S - getDP(l[x], i, i - 1);

		for (int j = head[x]; j; j = nxt[j]) {
			int y = to[j];
			if (y == l[x]) {
				continue;
			}
			for (int k = 0; k <= d[y]; ++k) {
				DP(x, i, k) = max(DP(x, i, k), getDP(y, i + !k, k - !!k) - getDP(y, i, i - 1) + S - add[x][i]);
			}
		}
		add[x][i] += i;
	}

	pp = ls;
}

void solve() {
	cin >> n >> m;
	m++;

	tot = 0;
	for (int i = 1; i <= n; ++i) {
		head[i] = 0;
	}

	for (int i = 2; i <= n; ++i) {
		int f;
		cin >> f;
		to[++tot] = i;
		nxt[tot] = head[f];
		head[f] = tot;
	}
	pre(1);

	pp = 0;
	for (int i = 1; i <= m; ++i) {
		it[1][i] = pp;
		pp += d[1];
	}
	memset(pool, 0, m * d[1] * 4);
	dfs(1);

	cout << getDP(1, 1, 0) << "\n";
}

int main() {
	ios::sync_with_stdio(false);
	cin.tie(nullptr);

	int t;
	cin >> t;

	while (t--) {
		solve();
	}

	return 0;
}

