inline int read() {
    int x = 0, m = 1;
    char ch = getchar();

    while (!isdigit(ch)) {
        if (ch == '-') m = -1;
        ch = getchar();
    }

    while (isdigit(ch)) {
        x = x * 10 + ch - 48;
        ch = getchar();
    }

    return x * m;
}

inline void write(int x) {
    if (x < 0) {
        putchar('-');
        write(-x);
        return;
    }

    if (x >= 10) write(x / 10);
    putchar(x % 10 + '0');
}

const int N = 8005, M = 805, inf = 1e9;

vector<int> v[N], pos[N];
int d[N], dfn[N], siz[N];
int f[N][M], h[N][M], s[N], w[N], F[N][M], pp[N];
int num;

void dfs(int ro) {
    dfn[ro] = ++num;
    siz[ro] = 1;
    pos[d[ro]].pb(ro);
    for (auto u : v[ro]) dfs(u), siz[ro] += siz[u];
}

void solve() {
    int n = read(), m = read() + 1;
    d[1] = 1;
    for (int i = 2; i <= n; i++) v[F[i][1] = read()].pb(i), d[i] = d[F[i][1]] + 1;
    num = 0;
    dfs(1);
    for (int i = 1; i <= m; i++) F[1][i] = 0;
    for (int i = 2; i <= n; i++) for (int j = 2; j <= m; j++) F[i][j] = F[F[i][1]][j - 1];
    for (int i = 1; i <= n; i++) F[i][0] = i;
    for (int i = 1; i <= n; i++) for (int j = 1; j <= m + 1; j++) f[i][j] = h[i][j] = -inf;
    for (int i = m; i >= 1; i--) {
        for (int j = 1; j <= n; j++) s[j] = pp[j] = 0, w[j] = -1;
        for (int j = m; j >= i; j--) {
            for (auto u : pos[j]) {
                int res = i, Max = 0;
                for (auto x : v[u]) res += h[x][i], Max = max(Max, f[x][i + 1] - h[x][i]);
                f[u][i] = max(f[u][i], res + Max);
            }
            if (j > i) {
                if (j + i - 1 <= m && pos[j + i - 1].size()) {
                    int x = j + i - 1, p = 0;
                    for (int z = 0; z < pos[x].size(); z++) {
                        int u = pos[x][z];
                        if (v[u].size()) {
                            int y = v[u][0];
                            w[u] = w[y] - f[y][i] + h[y][i] - s[u] + f[u][i] - h[F[y][i - 1]][i] + s[F[u][i - 1]];
                            pp[F[u][i - 1]] = 1;
                            p = 1;
                        }
                    }
                    if (!p) {
                        int y = pos[x][0], z = y;
                        w[y] = f[y][i] + (i - 1) * i;
                        pp[y] = 1;
                        for (int l = 1; l < i; l++) w[y] -= h[z][i], z = F[z][1], w[y] += s[z], pp[z] = 1;
                    }
                    auto chk = [&](int y, int z) -> int {
                        for (int x = 1; x < i; x++) {
                            y = F[y][1], z = F[z][1];
                            if (pp[y]) return y == z;
                        }
                        return 1;
                    };
                    for (int l = 1; l < pos[x].size(); l++) {
                        if (w[pos[x][l]] != -1 || w[pos[x][l - 1]] == -1) continue;
                        int y = pos[x][l], z = pos[x][l - 1], Y = y, Z = z;
                        if (!chk(y, z)) continue;
                        w[y] = w[z] - f[z][i] + f[y][i];
                        pp[y] = 1;
                        for (int r = 1; r < i && Y != Z; r++) {
                            w[y] = w[y] - h[Y][i] + h[Z][i];
                            Y = F[Y][1], Z = F[Z][1];
                            pp[Y] = 1;
                            w[y] = w[y] + s[Y] - s[Z];
                        }
                    }
                    for (int l = (int)pos[x].size() - 2; l >= 0; l--) {
                        if (w[pos[x][l]] != -1 || w[pos[x][l + 1]] == -1) continue;
                        int y = pos[x][l], z = pos[x][l + 1], Y = y, Z = z;
                        if (!chk(y, z)) continue;
                        w[y] = w[z] - f[z][i] + f[y][i];
                        pp[y] = 1;
                        for (int r = 1; r < i && Y != Z; r++) {
                            w[y] = w[y] - h[Y][i] + h[Z][i];
                            Y = F[Y][1], Z = F[Z][1];
                            pp[Y] = 1;
                            w[y] = w[y] + s[Y] - s[Z];
                        }
                    }
                }
                int t = 0;
                for (auto u : pos[j]) {
                    int res = i;
                    for (auto x : v[u]) res += h[x][i];
                    h[u][i] = max(h[u][i], res);
                    if (j + i - 1 <= m && pos[j + i - 1].size()) while (t < pos[j + i - 1].size() && dfn[pos[j + i - 1][t]] < dfn[u] + siz[u]) h[u][i] = max(h[u][i], w[pos[j + i - 1][t++]]);
                    if (F[u][1]) s[F[u][1]] += h[u][i];
                }
            }
        }
    }
    write(f[1][1]);
    putchar('\n');
    for (int i = 1; i <= n; i++) vector<int> ().swap(v[i]);
    for (int i = 1; i <= m; i++) vector<int> ().swap(pos[i]);
}

signed main() {
    int t = read();
    while (t--) solve();
}
